-- it, its text never changes again.
--
-- An installed copy applies it at its next start, in one transaction. 0005 created
-- SyncDevice with CHECK (slot IN (0, 1)), which SQLite cannot alter: the table is rebuilt
-- with slot 2 (the phone's) and a kind column (LAPTOP or PHONE; every existing row is a
-- laptop, the column's default), and SyncBooks and NumberBlock, which reference it, are
-- rebuilt with it, every row copied unchanged. Dropping a table drops its triggers: their
-- noDelete triggers and their capture triggers are written again.

-- ── 1. SyncDevice, SyncBooks and NumberBlock rebuilt ────────────────────────────

CREATE TABLE "SyncDevice__new" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "name" TEXT NOT NULL,
  "slot" INTEGER NOT NULL,
  "joinedAt" TEXT NOT NULL,
  "removedAt" TEXT,
  "removedReason" TEXT,
  "replacesDeviceId" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'LAPTOP',
  FOREIGN KEY ("replacesDeviceId") REFERENCES "SyncDevice__new" ("id") ON DELETE RESTRICT,
  CHECK ("slot" IN (0, 1, 2)),
  CHECK ("kind" IN ('LAPTOP', 'PHONE') AND ("slot" = 2) = ("kind" = 'PHONE')),
  CHECK ("removedAt" IS NULL OR "removedReason" IS NOT NULL)
) STRICT;

INSERT INTO "SyncDevice__new" ("id", "name", "slot", "joinedAt", "removedAt", "removedReason", "replacesDeviceId", "createdAt", "updatedAt")
  SELECT "id", "name", "slot", "joinedAt", "removedAt", "removedReason", "replacesDeviceId", "createdAt", "updatedAt" FROM "SyncDevice";

CREATE TABLE "SyncBooks__new" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "holderDeviceId" TEXT NOT NULL,
  "epoch" INTEGER NOT NULL,
  "handedAt" TEXT,
  "requestedByDeviceId" TEXT,
  "requestedAt" TEXT,
  "lastInvoiceNumber" TEXT,
  "lastReceiptNumber" TEXT,
  "forced" INTEGER NOT NULL DEFAULT 0,
  "reason" TEXT,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("holderDeviceId") REFERENCES "SyncDevice__new" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("requestedByDeviceId") REFERENCES "SyncDevice__new" ("id") ON DELETE RESTRICT,
  CHECK ("id" = 'books'),
  CHECK ("forced" IN (0, 1)),
  CHECK ("forced" = 0 OR "reason" IS NOT NULL)
) STRICT;

INSERT INTO "SyncBooks__new" ("id", "holderDeviceId", "epoch", "handedAt", "requestedByDeviceId", "requestedAt", "lastInvoiceNumber", "lastReceiptNumber", "forced", "reason", "updatedAt")
  SELECT "id", "holderDeviceId", "epoch", "handedAt", "requestedByDeviceId", "requestedAt", "lastInvoiceNumber", "lastReceiptNumber", "forced", "reason", "updatedAt" FROM "SyncBooks";

CREATE TABLE "NumberBlock__new" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "key" TEXT NOT NULL,
  "year" INTEGER NOT NULL,
  "blockIndex" INTEGER NOT NULL,
  "size" INTEGER NOT NULL,
  "deviceId" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "answer" TEXT,
  "answeredAt" TEXT,
  "used" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("deviceId") REFERENCES "SyncDevice__new" ("id") ON DELETE RESTRICT,
  CHECK ("kind" IN ('START', 'CLAIM', 'FALLBACK')),
  CHECK ("answer" IS NULL OR "answer" IN ('ACCEPTED', 'REFUSED')),
  CHECK ("size" > 0 AND "used" >= 0 AND "used" <= "size" AND "blockIndex" >= 0)
) STRICT;

INSERT INTO "NumberBlock__new" ("id", "key", "year", "blockIndex", "size", "deviceId", "kind", "answer", "answeredAt", "used", "createdAt", "updatedAt")
  SELECT "id", "key", "year", "blockIndex", "size", "deviceId", "kind", "answer", "answeredAt", "used", "createdAt", "updatedAt" FROM "NumberBlock";

DROP TRIGGER IF EXISTS "SyncDevice_sync_update";

UPDATE "SyncDevice" SET "replacesDeviceId" = NULL WHERE "replacesDeviceId" IS NOT NULL;

DROP TABLE "NumberBlock";

DROP TABLE "SyncBooks";

DROP TABLE "SyncDevice";

ALTER TABLE "SyncDevice__new" RENAME TO "SyncDevice";

ALTER TABLE "SyncBooks__new" RENAME TO "SyncBooks";

ALTER TABLE "NumberBlock__new" RENAME TO "NumberBlock";

CREATE UNIQUE INDEX "SyncDevice_active_slot" ON "SyncDevice" ("slot") WHERE "removedAt" IS NULL;

CREATE INDEX "NumberBlock_key_year_blockIndex_idx" ON "NumberBlock" ("key", "year", "blockIndex");

CREATE TRIGGER "SyncDevice_no_delete" BEFORE DELETE ON "SyncDevice"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:SyncDevice'); END;

CREATE TRIGGER "SyncBooks_no_delete" BEFORE DELETE ON "SyncBooks"
