WHEN (SELECT "capturing" = 1 AND "applying" = 0 FROM "SyncSession" WHERE "id" = 'session')
BEGIN
SELECT RAISE(ABORT, 'SYNC_UNSTAMPED') WHERE (SELECT "txId" FROM "SyncSession" WHERE "id" = 'session') IS NULL;
INSERT INTO "SyncOutbox" ("txId", "hlc", "tbl", "rowId", "op", "data")
  SELECT "txId", "hlc", 'SyncDevice', NEW."id", 'I', json_object('id', NEW."id", 'name', NEW."name", 'slot', NEW."slot", 'joinedAt', NEW."joinedAt", 'removedAt', NEW."removedAt", 'removedReason', NEW."removedReason", 'replacesDeviceId', NEW."replacesDeviceId", 'createdAt', NEW."createdAt", 'updatedAt', NEW."updatedAt", 'kind', NEW."kind") FROM "SyncSession" WHERE "id" = 'session';
END;

